apiVersion: networking.istio.io/v1alpha3
kind: Gateway
metadata:
  name: {{ .Values.nameOverride }}-gateway
  namespace: {{ .Values.namespace | default "default" }}
spec:
  selector:
    istio: {{ .Values.gateway.selector }}
  servers:
  {{- range .Values.gateway.servers }}
    - port:
        number: {{ .port.number }}
        name: {{ .port.name }}
        protocol: {{ .port.protocol }}
      hosts:
    {{- range .hosts }}
        - {{ . | quote }}
    {{- end }}
  {{- end }}

---

apiVersion: networking.istio.io/v1alpha3
kind: VirtualService
metadata:
  name: {{ .Values.nameOverride }}-vs
  namespace: {{ .Values.namespace | default "default" }}
spec:
  hosts:
  {{- range .Values.virtualService.hosts }}
    - {{ . | quote }}
  {{- end }}
  gateways:
  {{ .Values.nameOverride }}-gateway
  http:
  {{- range .Values.virtualService.http }}
    - match:
    {{- range .match }}
        - uri:
        {{ .uri.type }}: {{ .uri.value | quote }}
    {{- end }}
      route:
    {{- range .route }}
        - destination:
            host:  {{ .destination.host | quote }}
            port:
